import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiStation","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/index.md","filePath":"modules/station/index.md","lastUpdated":0}`),a={name:`modules/station/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakistation" tabindex="-1">EmakiStation <a class="header-anchor" href="#emakistation" aria-label="Permalink to “EmakiStation”">​</a></h1><p>EmakiStation 是 Emaki 系列的通用合成工作站模块。它把「按配方投入材料、排入队列、到点领取产物」这条流程做成可配置的 GUI 工作站，并额外提供一套完全独立的分解站。</p><p>合成侧是三页式界面（配方目录 → 材料预览 → 合成队列），队列串行推进。材料从「背包 + 仓库」合并池扣除，安装 EmakiStorage 后仓库参与供料；产物按配置路由到仓库或背包，两边都放不下时进入待领取状态，不会掉落也不会销毁。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.1.3</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-station-api:1.1.3</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.station.EmakiStationPlugin</code></td></tr><tr><td>主命令</td><td><code>/emakistation</code></td></tr><tr><td>别名</td><td><code>/estation</code>、<code>/est</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiStorage、PlaceholderAPI</td></tr><tr><td>描述符基线</td><td><code>api-version: &quot;1.21.8&quot;</code>、<code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakistation.use</code>（默认 true）、<code>emakistation.purchase</code>（默认 true）、<code>emakistation.dismantle</code>（默认 true）、<code>emakistation.reload</code>（op）、<code>emakistation.debug</code>（op）、<code>emakistation.admin</code>（op）</td></tr></tbody></table><p>POM/runtime/API 与默认 <code>config.yml</code> 的版本值是 <code>1.1.3</code>；源码内部的 <code>AppConfig.CURRENT_VERSION = &quot;1.0.2&quot;</code> 是配置迁移结构常量，两者用途不同，不要混用。</p><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/emakistation</code> 的 9 个功能子命令（另有 <code>help</code>）、6 个权限节点与两个访问权限前缀。</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 的 <code>queue</code>、<code>limits</code>、<code>storage</code>、<code>persistence</code>、<code>gui</code> 五段，含全键表与默认值。</td></tr><tr><td><a href="./stations.html">工作站定义</a></td><td><code>stations/&lt;id&gt;.yml</code> 的布局、权限、队列参数、材料通道、产物路由与条件门。</td></tr><tr><td><a href="./recipes.html">配方定义</a></td><td><code>recipes/&lt;配方&gt;.yml</code> 的归属、材料、产物、耗时、货币成本、动作段与两种条件门。</td></tr><tr><td><a href="./queue.html">合成队列</a></td><td>队列长度的三个来源、串行推进、取消退还与待领取状态。</td></tr><tr><td><a href="./queue-costs.html">付费队列位</a></td><td><code>queue_costs.yml</code> 的档位、逐格计价、三道开关与 <code>unlocks.yml</code> 已购存档。</td></tr><tr><td><a href="./dismantle.html">物品分解</a></td><td>独立分解站与分解配方的 <code>item_sources</code>、<code>rolls</code>、<code>pool</code> 权重抽取。</td></tr><tr><td><a href="./gui.html">界面模板</a></td><td>四份 GUI 模板的槽位类型、占位符全集与「必须显式写 <code>type:</code>」约束。</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td><code>emaki-station-api</code> 的门面、查询与操作接口及线程约束。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td><code>StationCraftSubmitEvent</code>、<code>StationCraftCancelEvent</code>、<code>StationCraftCompletedEvent</code>。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><ul><li><strong>无序集合匹配</strong>：配方只看材料种类与总数，不看摆放位置，没有 shaped 概念。<code>item_sources</code> 是「任意其一」集合，数量按集合内总数计算——需要 64 个时，30 个 coal 加 34 个 charcoal 也算满足。</li><li><strong>背包与仓库合并供料</strong>：两个通道都开启时，材料来自合并池并优先扣背包。玩家看不到通道切换按钮，界面里显示的「拥有」就是两边合计。</li><li><strong>串行单线队列</strong>：一个玩家在一个工作站只有一条队列，只有队首在推进。<code>waiting</code> 与 <code>running</code> 占用队列长度，<code>pending_claim</code> 不占用。</li><li><strong>队列长度三来源</strong>：基础长度、<code>emakistation.queue.&lt;n&gt;</code> 权限档、付费购买。权限档<strong>取代</strong>基础长度，付费额度<strong>叠加</strong>在其上，最终统一被 <code>max_length</code> 截断。</li><li><strong>产物永不丢失</strong>：所有配置目标都放不下时，条目转为待领取，等玩家用 <code>/emakistation claim</code> 或界面按钮领取。</li><li><strong>分解站完全独立</strong>：分解站与合成站 ID 互不关联，各自在 <code>stations_dismantle/</code> 与 <code>recipes_dismantle/</code> 目录加载，不是工作站的第四页。</li></ul><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to “文件结构”">​</a></h2><p>服务器运行后，EmakiStation 主要使用以下文件：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStation/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ queue_costs.yml</span></span>
<span class="line"><span>├─ stations/</span></span>
<span class="line"><span>│  └─ blacksmith.yml</span></span>
<span class="line"><span>├─ recipes/</span></span>
<span class="line"><span>│  └─ example_recipe.yml</span></span>
<span class="line"><span>├─ stations_dismantle/</span></span>
<span class="line"><span>│  └─ example_dismantle_station.yml</span></span>
<span class="line"><span>├─ recipes_dismantle/</span></span>
<span class="line"><span>│  └─ example_dismantle_recipe.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ station_catalog.yml</span></span>
<span class="line"><span>│  ├─ station_preview.yml</span></span>
<span class="line"><span>│  ├─ station_queue.yml</span></span>
<span class="line"><span>│  └─ station_dismantle.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;玩家 UUID&gt;/</span></span>
<span class="line"><span>│     └─ unlocks.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置：队列默认值、容量上限、仓库通道、持久化、界面节流。</td></tr><tr><td><code>queue_costs.yml</code></td><td>付费队列位档位。业务数据文件，只在缺失时释放一次，版本升级不覆盖管理员内容。</td></tr><tr><td><code>stations/&lt;id&gt;.yml</code></td><td>合成工作站定义。文件名与 <code>id</code> 一致。</td></tr><tr><td><code>recipes/&lt;配方&gt;.yml</code></td><td>合成配方定义。一个文件一条配方，归属由配方侧的 <code>station_ids</code> 声明。</td></tr><tr><td><code>stations_dismantle/&lt;id&gt;.yml</code></td><td>分解站定义，与合成站互不关联。</td></tr><tr><td><code>recipes_dismantle/&lt;配方&gt;.yml</code></td><td>分解配方定义，含输入物品与产物概率池。</td></tr><tr><td><code>gui/*.yml</code></td><td>四份界面模板：配方目录、材料预览、合成队列、分解界面。</td></tr><tr><td><code>data/&lt;玩家 UUID&gt;/unlocks.yml</code></td><td>每玩家已购队列位存档，插件自动维护；额度为空时不生成。见<a href="./queue-costs.html">付费队列位</a>。</td></tr><tr><td><code>lang/*.yml</code></td><td>命令、界面、预检与控制台文案。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><ol><li>把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiStation-*.jar</code> 放入服务器 <code>plugins/</code>。</li><li>不要把 <code>emaki-station-api-*.jar</code> 放进 <code>plugins/</code>；API Jar 只作为开发者的编译依赖。</li><li>首次启动后检查 <code>plugins/EmakiStation/config.yml</code> 与示例工作站 <code>stations/blacksmith.yml</code>。</li><li>打开示例工作站：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation open blacksmith</span></span></code></pre></div><ol start="5"><li>查看自己的队列与领取产物：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation queue</span></span>
<span class="line"><span>/emakistation claim</span></span></code></pre></div><ol start="6"><li>修改配置后重载：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation reload</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>工作站的 <code>channels.backpack</code> 与 <code>channels.storage</code> 不能同时为 false，否则该工作站会被拒绝加载——能打开但永远用不了，不如启动时就报错。</li><li><code>channels.default</code> 是保留键，当前不再生效。合并通道之后没有「停在哪个通道」这回事，源码仍会读取但没有任何路径消费它，留着只为让旧配置不报未知键。</li><li>仓库通道除了 <code>storage.enabled: true</code>，还需要 EmakiStorage 提供 <code>emakistorage:atomic_batch</code> 能力才会启用。缺少该能力时不会退化为逐个取出，因为那会让材料在背包里闪现一次。</li><li><code>progress_mode: offline</code> 只表示「计时继续」，不表示「离线发货」。离线期间到点的条目只是已到期，真正结算发生在玩家下次上线时。</li><li>三份布局文件（<code>layout</code>、<code>preview_layout</code>、<code>queue_layout</code>）都必须存在，缺任何一个都会在启动预检里报 <code>missing_layout</code>。</li><li><strong>确定性最大流材料分配</strong>：提交时把背包物品堆与仓库库存一起建图，在全部需求之间寻找完整分配，不再依赖配方声明顺序。约束更窄的 matcher 材料会优先参与建图，但最终仍以全局可行分配为准；若分配失败，表示当前候选材料确实无法同时满足全部需求。</li><li><strong>未接线面</strong>：EmakiStation 不注册任何动作段 id，也不注册 PlaceholderAPI 扩展。配方里的 <code>actions.pre</code> / <code>success</code> / <code>failure</code>、<code>result.actions</code>，以及工作站与分解站级别的 <code>condition</code>，都会被解析并保存但当前没有执行入口；<code>limits.batch_multiplier_max</code> 同样只被解析、不参与校验。详见<a href="./recipes.html">配方定义</a>、<a href="./stations.html">工作站定义</a>、<a href="./dismantle.html">物品分解</a>与<a href="./configuration.html">配置详解</a>。</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};